/usr/bin/bash -lc "python3 - <<'PY'
import json
p=json.load(open('.exp_agent/round_01/plan.json'))
path='entry/src/main/ets/pages/Index.ets'
lines=open(path).read().splitlines()
planned=[(r['rule'], f['relative_path'], f['locations']) for r in p['rules'] for f in r['files']]
for rule, rel, locs in planned:
  bad=[]
  for loc in locs:
    line=lines[loc['line']-1]
    if loc['line'] == 34:
      ok='.id' in line and '@State' not in line
    else:
      ok='this.result +=' not in line
    if not ok: bad.append((loc['line'], line))
  print(rule, 'locations=',len(locs), 'unrepaired=',len(bad))
  if bad: print(bad[:5])
print('state_fields:', [x for x in lines if '@State' in x])
print('state_writes:', [f'{i+1}: {x}' for i,x in enumerate(lines) if 'this.result +=' in x])
PY"

